/**
 * Omni Sweep — Goods and Gear: The Ultimate Adventurer's Guide
 * (Kenzer & Company, 2004; Kingdoms of Kalamar). Every purchasable
 * equipment entry and the book's one magic item (the outsider's
 * talisman), parsed from the D&D columns of the book's dual-system
 * tables. Names already in the catalog were skipped (price
 * disagreements are logged in the omni-sweep report, not edited).
 * Summaries/notes are mechanical facts in our own words.
 */
import type { EquipmentItem, MagicItemDefinition } from "@/engine/types";

export const GG_MAGIC_ITEMS_OMNI: MagicItemDefinition[] = [
  {
    "id": "talisman-outsiders-symbol",
    "name": "Talisman (Outsider's Symbol)",
    "category": "wondrous-slotless",
    "cost": "100 gp x the creature's Hit Dice",
    "summary": "Crafted item bearing the personal symbol of an individual outsider, usually in amulet form; used when summoning that outsider to improve its reaction and reduce its chance of escaping the binding circle (a masterwork talisman grants an additional +1 to the reaction modifier and escape DC). Base cost is 100 gp times the creature's Hit Dice, adjusted by plane of origin (Ethereal, Shadow, Astral and Elemental +0%, Positive Energy +5%, with further modifiers per Table 7-11). Destroying a creature's talisman deals it 1d10 nonlethal damage",
    "source": "Goods and Gear: The Ultimate Adventurer's Guide, Chapter 7: Tools, Gear and Equipment, p. 163",
    "sourceUrl": "",
    "ruleset": "core"
  },
];

